#!/usr/bin/env node
/**
 * Writes the three generated files in assets/ (the public folder) from two sources: the site address
 * in apps/docs/data/site.json and the post list in apps/docs/data/blog-posts.json.
 *   rss.xml      the blog feed
 *   robots.txt   allow everything, point at the sitemap
 *   sitemap.xml  every page in apps/docs/routes, with lastmod
 * Static files, not API routes (Devora.js API routes always answer JSON), and the app's built-in
 * sitemap is off (app.config.ts) because it has no lastmod and cannot take an address from data.
 * Runs before every build (package.json "prebuild" and scripts/build-docs.sh), so none of them can
 * drift from the routes or the blog index. Changing the domain is one edit: data/site.json.
 *
 * lastmod: a blog post uses its own date; any other page uses the date of the last commit that
 * touched its route file. On a shallow clone (a deploy), git cannot tell, so the value already in
 * the committed sitemap.xml is kept for that page; a page git has not seen yet uses its file date.
 */
import { execFileSync } from "node:child_process";
import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import path from "node:path";

const root = path.resolve(path.dirname(new URL(import.meta.url).pathname), "..");
const SITE = JSON.parse(readFileSync(path.join(root, "apps/docs/data/site.json"), "utf-8")).url.replace(/\/+$/, "");
const { author, posts } = JSON.parse(readFileSync(path.join(root, "apps/docs/data/blog-posts.json"), "utf-8"));

const esc = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const rfc822 = (iso) => new Date(`${iso}T00:00:00Z`).toUTCString();
const sorted = posts.filter((p) => p.date && !p.draft).sort((a, b) => b.date.localeCompare(a.date));

const items = sorted
  .map(
    (p) => `    <item>
      <title>${esc(p.title)}</title>
      <link>${SITE}/blog/${p.slug}</link>
      <guid isPermaLink="true">${SITE}/blog/${p.slug}</guid>
      <pubDate>${rfc822(p.date)}</pubDate>
      <dc:creator>${esc(author.name)}</dc:creator>
      ${(p.tags ?? []).map((t) => `<category>${esc(t)}</category>`).join("\n      ")}
      <description>${esc(p.description)}</description>
    </item>`
  )
  .join("\n");

const xml = `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom" xmlns:dc="http://purl.org/dc/elements/1.1/">
  <channel>
    <title>Devora.js blog</title>
    <link>${SITE}/blog</link>
    <description>Release notes and design write-ups from the Devora.js project.</description>
    <language>en</language>
    <lastBuildDate>${rfc822(sorted[0].date)}</lastBuildDate>
    <atom:link href="${SITE}/rss.xml" rel="self" type="application/rss+xml" />
${items}
  </channel>
</rss>
`;
writeFileSync(path.join(root, "assets/rss.xml"), xml);
console.log(`assets/rss.xml: ${sorted.length} posts`);

writeFileSync(
  path.join(root, "assets/robots.txt"),
  `# Everything on the docs site is public and meant to be indexed.
# Generated by scripts/build-seo-files.mjs from apps/docs/data/site.json.
User-agent: *
Allow: /

Sitemap: ${SITE}/sitemap.xml
`
);
console.log("assets/robots.txt");

// ---- sitemap.xml -----------------------------------------------------------
const routesDir = path.join(root, "apps/docs/routes");
const files = [];
(function walk(dir) {
  for (const name of readdirSync(dir).sort()) {
    const full = path.join(dir, name);
    if (statSync(full).isDirectory()) walk(full);
    else if (/\.tsx$/.test(name)) files.push(full);
  }
})(routesDir);

const draftSlugs = new Set(posts.filter((p) => p.draft || !p.date).map((p) => p.slug));
const postDates = new Map(posts.map((p) => [p.slug, p.date]));

const sitemapPath = path.join(root, "assets/sitemap.xml");
const previous = new Map();
if (existsSync(sitemapPath)) {
  for (const m of readFileSync(sitemapPath, "utf-8").matchAll(/<loc>([^<]+)<\/loc>\s*<lastmod>([^<]+)<\/lastmod>/g)) previous.set(m[1], m[2]);
}
let shallow = true;
try {
  shallow = execFileSync("git", ["rev-parse", "--is-shallow-repository"], { cwd: root, encoding: "utf-8" }).trim() !== "false";
} catch { /* not a git checkout */ }

function gitDate(file) {
  if (shallow) return undefined;
  try {
    const out = execFileSync("git", ["log", "-1", "--format=%cs", "--", path.relative(root, file)], { cwd: root, encoding: "utf-8" }).trim();
    return out || undefined;
  } catch { return undefined; }
}

const entries = [];
for (const file of files) {
  const rel = path.relative(routesDir, file).replace(/\.tsx$/, "");
  const route = rel === "index" ? "/" : "/" + rel.replace(/\/index$/, "");
  const slug = route.startsWith("/blog/") ? route.slice("/blog/".length) : undefined;
  if (slug && draftSlugs.has(slug)) continue;
  if (/\[/.test(rel)) continue;
  const loc = route === "/" ? `${SITE}/` : `${SITE}${route}`;
  // Tracked by the page's own file; blog posts by their publish date.
  const lastmod = (slug && postDates.get(slug)) || gitDate(file) || previous.get(loc) || statSync(file).mtime.toISOString().slice(0, 10);
  entries.push({ loc, lastmod });
}
entries.sort((a, b) => a.loc.localeCompare(b.loc));
const urls = entries
  .map((e) => `  <url><loc>${esc(e.loc)}</loc>${e.lastmod ? `<lastmod>${e.lastmod}</lastmod>` : ""}</url>`)
  .join("\n");
writeFileSync(
  sitemapPath,
  `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${urls}
</urlset>
`
);
console.log(`assets/sitemap.xml: ${entries.length} pages, ${entries.filter((e) => e.lastmod).length} with lastmod`);
